개요 하이컴에서 데이터를 일일이 손으로 클릭해서 받고 정리하는 것은 쉽지 않은 일이다. 조건을 지정하는 URL을 주어서 받아내는 방법을 소개한다.
코드 HTTP.jl 1 for y = 2019:2024 url = replace(&#34;https://ncss.hycom.org/thredds/ncss/GLBy0.08/expt_93.0/ts3z/$y?var=water_temp &amp;north=36.88 &amp;west=129.52 &amp;east=130.24 &amp;south=36.32 &amp;disableProjSubset=on &amp;horizStride=1 &amp;time_start=$y-01-01T00%3A00%3A00Z &amp;time_end=$y-12-31T21%3A00%3A00Z &amp;timeStride=1 &amp;vertCoord=0 &amp;accept=netcdf4&#34;, &#39;\n&#39; =&gt; &#34;&#34;, &#34; &#34; =&gt; &#34;&#34;) @time response = HTTP.get(url) open(&#34;data_$y.nc4&#34;, &#34;w&#34;) do f write(f, response.body) end end 가령 위의 코드는 GLBy0.08의 93번 실험에서, 2019년부터 2024년까지의 해수면온도(SST, Sea Surface Temperature)를 위도 36.32~36.88, 경도 129.52~130.24의 범위에서 세 시간 간격의 데이터를 받아내는 코드다.
NCDatasets.jl 2 data_ = [] for y = 2019:2024 ds = NCDataset(&#34;data_$y.nc4&#34;) push!(data_, DataFrame([ds[&#34;time&#34;][:] reshape(ds[&#34;water_temp&#34;][:, :, 1, :], 150, :)&#39;], [&#34;t&#34;; repeat(&#34;i&#34; .* string.(1:10), outer = 15) .* repeat(&#34;j&#34; .* string.(1:15), inner = 10)])) close(ds) end 다운로드 되는 파일은 NetCDF-4(Network Common Data Form version 4)를 의미하는 *.nc4 파일이다. 고차원의 데이터를 다루기 위해 널리 쓰이지만, 이 가이드에서는 DataFrames.jl로 데이터프레임을 만들고 있다
저장 _data_ = vcat(data_...) _data_.t = Date.(_data_.t) _data_ = combine(groupby(_data_, :t), names(_data_, Not(:t)) .=&gt; mean .=&gt; names(_data_, Not(:t))) CSV.write(&#34;data_GLBy0.08_expt_93.0.csv&#34;, _data_) tnsr = reshape(Matrix(_data_[:, 2:end])&#39;, 10, 15, :) @save &#34;data_tnsr.jld2&#34; tnsr # @load &#34;data_tnsr.jld2&#34;; tnsr JLD2.jl을 통해서 텐서 그대로를 저장할 수도 있고, 쓰기 간편한 CSV.jl로 저장하는 방법도 있다.
전체 코드 using HTTP, NCDatasets, DataFrames, Dates, CSV, JLD2, StatsBase for y = 2019:2024 url = replace(&#34;https://ncss.hycom.org/thredds/ncss/GLBy0.08/expt_93.0/ts3z/$y?var=water_temp &amp;north=36.88 &amp;west=129.52 &amp;east=130.24 &amp;south=36.32 &amp;disableProjSubset=on &amp;horizStride=1 &amp;time_start=$y-01-01T00%3A00%3A00Z &amp;time_end=$y-12-31T21%3A00%3A00Z &amp;timeStride=1 &amp;vertCoord=0 &amp;accept=netcdf4&#34;, &#39;\n&#39; =&gt; &#34;&#34;, &#34; &#34; =&gt; &#34;&#34;) @time response = HTTP.get(url) open(&#34;data_$y.nc4&#34;, &#34;w&#34;) do f write(f, response.body) end end # ds = NCDataset(&#34;data_$y.nc4&#34;) # # ds.attrib # # keys(ds) # # ds[&#34;water_temp&#34;][:, :, 1, :] # CSV.write(&#34;lon.csv&#34;, DataFrame(i = 1:10, x = round.(ds[&#34;lon&#34;][:], digits = 2))) # CSV.write(&#34;lat.csv&#34;, DataFrame(j = 1:15, y = round.(ds[&#34;lat&#34;][:], digits = 2))) # close(ds) data_ = [] for y = 2019:2024 ds = NCDataset(&#34;data_$y.nc4&#34;) push!(data_, DataFrame([ds[&#34;time&#34;][:] reshape(ds[&#34;water_temp&#34;][:, :, 1, :], 150, :)&#39;], [&#34;t&#34;; repeat(&#34;i&#34; .* string.(1:10), outer = 15) .* repeat(&#34;j&#34; .* string.(1:15), inner = 10)])) close(ds) end _data_ = vcat(data_...) _data_.t = Date.(_data_.t) _data_ = combine(groupby(_data_, :t), names(_data_, Not(:t)) .=&gt; mean .=&gt; names(_data_, Not(:t))) CSV.write(&#34;data_GLBy0.08_expt_93.0.csv&#34;, _data_) tnsr = reshape(Matrix(_data_[:, 2:end])&#39;, 10, 15, :) @save &#34;data_tnsr.jld2&#34; tnsr # @load &#34;data_tnsr.jld2&#34;; tnsr 니뇨 3.4 다음은 니뇨 3.4Niño 3.4이라고 해서3 위도 5°S~5°N, 경도 170°W~120°W의 해수면온도의 평균값을 받을 수 있는 코드다.
using HTTP, NCDatasets, DataFrames, Dates, CSV, JLD2, StatsBase, ProgressMeter using Base.Threads @showprogress @threads for day in Date(2019, 1, 1):Date(2024, 9, 5) try str_day = string(day) (&#34;data_$str_day.nc4&#34; |&gt; isfile) &amp;&amp; continue url = replace(&#34;https://ncss.hycom.org/thredds/ncss/GLBy0.08/expt_93.0/ts3z/$(Year(day).value)?var=water_temp &amp;north=5 &amp;west=120 &amp;east=170 &amp;south=-5 &amp;disableProjSubset=on &amp;horizStride=1 &amp;time_start=$(day)T00%3A00%3A00Z &amp;time_end=$(day)T21%3A00%3A00Z &amp;timeStride=1 &amp;vertCoord=0 &amp;accept=netcdf4&#34;, &#39;\n&#39; =&gt; &#34;&#34;, &#34; &#34; =&gt; &#34;&#34;) # @time response = HTTP.get(url) response = HTTP.get(url) open(&#34;data_$str_day.nc4&#34;, &#34;w&#34;) do f write(f, response.body) end catch e @warn e end end nc4_ = filter(endswith(&#34;.nc4&#34;), readdir()) @time data_ = CSV.read(&#34;data_form.csv&#34;, DataFrame) @showprogress for k in eachindex(nc4_) NCDataset(nc4_[k]) do ds df = DataFrame([ds[&#34;time&#34;][:] reshape(ds[&#34;water_temp&#34;][:, :, 1, :], 251*626, :)&#39;], [&#34;t&#34;; repeat(&#34;i&#34; .* string.(1:626), outer = 251) .* repeat(&#34;j&#34; .* string.(1:251), inner = 626)]) df.t = Date.(df.t) data_[k, :] = combine(groupby(df, :t), names(df, Not(:t)) .=&gt; mean .=&gt; names(df, Not(:t)))[1, :] end end CSV.write(&#34;data_GLBy0.08_expt_93.0.csv&#34;, data_) tnsr = reshape(Matrix(data_[:, 2:end])&#39;, 626, 251, :) @save &#34;data_tnsr.jld2&#34; tnsr https://github.com/JuliaWeb/HTTP.jl&#160;&#x21a9;&#xfe0e;
